<script setup>import PartnerLayout from '@/Layouts/PartnerLayout.vue';import Pagination from '@/Components/Partner/Pagination.vue';defineProps({commissions:Object,earnings:Array,rates:Array,collections:Array,outstanding:Array});</script><template><PartnerLayout title="Revenue & commissions"><p class="mb-6 text-slate-600">Commission is earned on fully paid, active subscriptions at the product's configured rate. New allocations include VAT in the subscription receipt base and divide it into five shares. Non-subscription items and credit-funded portions are excluded. Refunds reverse the invoice commission. Earned amounts shown here are not payout confirmations.</p><div class="grid gap-5 md:grid-cols-3"><section v-for="[title,rows] in [['Earned commission',earnings],['Verified client collections',collections],['Outstanding client invoices',outstanding]]" :key="title" class="rounded-xl bg-white p-6"><h2 class="font-bold">{{ title }}</h2><p v-for="row in rows" :key="row.currency" class="mt-3 text-2xl">{{ row.currency }} {{ row.total }}</p><p v-if="!rows.length" class="mt-3 text-slate-500">No balance yet</p></section></div><section class="my-6 rounded-xl bg-white p-6"><h2 class="text-xl font-bold">Current product commission rates</h2><p v-for="product in rates" :key="product.name" class="mt-3">{{ product.name }}: <strong>{{ product.partner_commission_rate }}%</strong></p></section><h2 class="mb-4 text-xl font-bold">Commission history</h2><article v-for="entry in commissions.data" :key="entry.id" class="mb-3 rounded-xl bg-white p-5"><strong>{{ entry.product.name }} ? {{ entry.invoice.invoice_number }}</strong><p class="mt-2">{{ entry.currency }} {{ entry.amount }} ? {{ entry.status }}</p><p class="mt-2 text-sm text-slate-500">{{ entry.rate }}% of {{ entry.currency }} {{ entry.base_amount }}</p></article><p v-if="!commissions.data.length">No commissions earned yet.</p><Pagination :page="commissions"/></PartnerLayout></template>
